BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(21);
INSERT INTO auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) VALUES
('fc000000-0000-4000-8000-000000000001','authenticated','authenticated','discussion-admin@local.test','{}','{}'),
('fc000000-0000-4000-8000-000000000002','authenticated','authenticated','discussion-outsider@local.test','{}','{}');
INSERT INTO public.organizations(id,name,username,type,join_code) VALUES('fc100000-0000-4000-8000-000000000001','Discussion fixtures','discussion-fixtures','school','739991');
INSERT INTO public.organization_members(organization_id,user_id,role,status) VALUES('fc100000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','admin','active');
INSERT INTO plugin_data.csf_terms(id,organization_id,code,label,school_year,semester) VALUES('fc200000-0000-4000-8000-000000000001','fc100000-0000-4000-8000-000000000001','F30','Fall 2030','2030-2031','fall');
INSERT INTO plugin_data.csf_sheet_sync_destinations(id,organization_id,spreadsheet_file_id,sheet_id,kind,term_id,is_test,configured_by,managed_headers) VALUES('fc400000-0000-4000-8000-000000000001','fc100000-0000-4000-8000-000000000001','fictional-discussion-copy',0,'applications','fc200000-0000-4000-8000-000000000001',true,'fc000000-0000-4000-8000-000000000001','["Record ID","Comments","Source version"]');
INSERT INTO plugin_data.csf_sheet_sync_bindings(organization_id,destination_id,record_kind,record_id,logical_key,sheet_id) VALUES('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001','application','fc600000-0000-4000-8000-000000000001','fixture',0);
INSERT INTO plugin_data.csf_cohorts(id,organization_id,graduation_year,label) VALUES('fc500000-0000-4000-8000-000000000001','fc100000-0000-4000-8000-000000000001',2033,'Class of 2033');
INSERT INTO plugin_data.csf_profiles(id,organization_id,first_name,last_name,normalized_first_name,normalized_last_name) VALUES('fc300000-0000-4000-8000-000000000001','fc100000-0000-4000-8000-000000000001','Fictional','Student','fictional','student');
INSERT INTO plugin_data.csf_term_applications(id,organization_id,profile_id,cohort_id,term_id,source,status) VALUES('fc600000-0000-4000-8000-000000000001','fc100000-0000-4000-8000-000000000001','fc300000-0000-4000-8000-000000000001','fc500000-0000-4000-8000-000000000001','fc200000-0000-4000-8000-000000000001','manual','submitted');
SELECT plugin_data.csf_set_sheet_sync_destination_state('fc100000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',true,true,'available');
UPDATE plugin_data.csf_sheet_sync_destinations SET discussion_transport='column' WHERE organization_id='fc100000-0000-4000-8000-000000000001';
CREATE TEMP TABLE obs_lease AS SELECT plugin_data.csf_claim_sheet_sync_destination('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',true) v;
UPDATE plugin_data.csf_sheet_sync_bindings SET last_export_version=md5(plugin_data.csf_sheet_sync_destination_snapshot(organization_id,destination_id,record_kind,record_id)::text),last_export_comments='Original' WHERE destination_id='fc400000-0000-4000-8000-000000000001';
CREATE FUNCTION pg_temp.obs_request(payload jsonb) RETURNS jsonb LANGUAGE sql AS $$ SELECT plugin_data.csf_record_sheet_sync_change('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001','application','fc600000-0000-4000-8000-000000000001',(SELECT last_export_version FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id='fc400000-0000-4000-8000-000000000001'),md5(payload::text),payload,(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease)) $$;
CREATE FUNCTION pg_temp.obs_complete(valid boolean) RETURNS jsonb LANGUAGE sql AS $$ SELECT plugin_data.csf_complete_sheet_sync_observation('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease),valid) $$;
CREATE FUNCTION pg_temp.obs_review(id uuid) RETURNS jsonb LANGUAGE sql AS $$ SELECT plugin_data.csf_review_sheet_sync_change('fc100000-0000-4000-8000-000000000001','fc000000-0000-4000-8000-000000000001',id,true,'Reviewed complete observation') $$;
CREATE TEMP TABLE obs_changes(k text,v jsonb);
INSERT INTO obs_changes VALUES('original',pg_temp.obs_request('{"action":"approved"}'));
SELECT extensions.is((SELECT observation_state FROM plugin_data.csf_sheet_sync_destinations WHERE id='fc400000-0000-4000-8000-000000000001'),'checking','claim holds acceptance while observation is incomplete');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original'))$$,'P0001','Complete a valid Sheet observation before accepting this change.','in-progress proposal cannot be accepted');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_request('{"action":"invalid"}')$$,'P0001','Unsupported Sheet change.','malformed replacement fails validation');
SELECT extensions.is(pg_temp.obs_complete(false)->>'status','invalid','invalid observation is persisted separately from failed row RPC');
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original')),'stale','malformed replacement retires original pending action');
SELECT extensions.is((SELECT last_seen_request FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id='fc400000-0000-4000-8000-000000000001'),'{}'::jsonb,'invalid observation resets pending input baseline');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_complete(true)$$,'P0001','Start a new poll after an invalid observation.','same failed poll cannot overwrite invalid result');
SELECT plugin_data.csf_release_sheet_sync_destination('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease));
UPDATE obs_lease SET v=plugin_data.csf_claim_sheet_sync_destination('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',true);
INSERT INTO obs_changes VALUES('repaired',pg_temp.obs_request('{"action":"approved"}'));
SELECT extensions.is((SELECT v->>'status' FROM obs_changes WHERE k='repaired'),'pending','repair recreates a pending observation');
SELECT extensions.isnt((SELECT v->>'id' FROM obs_changes WHERE k='repaired'),(SELECT v->>'id' FROM obs_changes WHERE k='original'),'repair preserves withdrawn history');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_request(jsonb_build_object('action','comment','previous_comments','Original','comments',repeat('x',10001)))$$,'P0001','Sheet change exceeds the size limit.','oversized replacement fails without becoming actionable');
SELECT pg_temp.obs_complete(false);
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='repaired')),'stale','oversized replacement retires pending action');
SELECT plugin_data.csf_release_sheet_sync_destination('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease));
UPDATE obs_lease SET v=plugin_data.csf_claim_sheet_sync_destination('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',true);
INSERT INTO obs_changes VALUES('network',pg_temp.obs_request('{"action":"approved"}'));
UPDATE plugin_data.csf_sheet_sync_destinations SET poll_lease_expires_at=clock_timestamp()-interval '1 second' WHERE id='fc400000-0000-4000-8000-000000000001';
SELECT extensions.throws_ok($$SELECT pg_temp.obs_complete(false)$$,'P0001','Sync lease expired or access changed.','expired notification cannot mutate observation');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='network'))$$,'P0001','Complete a valid Sheet observation before accepting this change.','failed notification and expired lease leave acceptance held');
UPDATE obs_lease SET v=plugin_data.csf_claim_sheet_sync_destination('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',true);
SELECT extensions.is(pg_temp.obs_complete(true)->>'status','valid','complete repaired read can validate observation');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='network'))$$,'P0001','Complete a valid Sheet observation before accepting this change.','valid observation still holds during active poll');
SELECT plugin_data.csf_release_sheet_sync_destination('fc100000-0000-4000-8000-000000000001','fc400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease));
SELECT extensions.is(pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='network'))->>'status','accepted','completed released observation permits reviewed action');
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original')),'stale','prior withdrawal history remains unchanged');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_complete(false)$$,'P0001','Sync lease expired or access changed.','released token cannot invalidate a later observation');
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='network')),'accepted','failed old receipt preserves staff decision');
SELECT extensions.ok(NOT has_function_privilege('authenticated','plugin_data.csf_complete_sheet_sync_observation(uuid,uuid,uuid,boolean)','EXECUTE'),'browser cannot complete observation');
SELECT extensions.ok(has_function_privilege('service_role','plugin_data.csf_complete_sheet_sync_observation(uuid,uuid,uuid,boolean)','EXECUTE'),'worker can complete observation');
SELECT * FROM extensions.finish();
ROLLBACK;
